CREATE TABLE IF NOT EXISTS MOVIES (ID VARCHAR(255) PRIMARY KEY, MEDIA_ENTRY JSON DEFAULT NULL NULL, CACHE_DATE TIMESTAMP(9) NOT NULL);
CREATE TABLE IF NOT EXISTS BOOKMARKS (ID VARCHAR(255) PRIMARY KEY, BOOKMARKED_AT TIMESTAMP(9) NOT NULL, IS_BOOKMARKED BOOLEAN DEFAULT TRUE NOT NULL, COLOUR VARCHAR(63) DEFAULT NULL NULL, CONSTRAINT FK_BOOKMARKS_ID__ID FOREIGN KEY (ID) REFERENCES MOVIES(ID) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS WATCHED (ID VARCHAR(255) PRIMARY KEY, WATCHED_AT TIMESTAMP(9) NOT NULL, CONSTRAINT FK_WATCHED_ID__ID FOREIGN KEY (ID) REFERENCES MOVIES(ID) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS MIGRATIONS (ID BIGINT AUTO_INCREMENT PRIMARY KEY, "name" VARCHAR(255) NOT NULL, HASH VARCHAR(255) NOT NULL);
